	const upsert = (collectionName, field, value, data) => {
		let record
		try {
			record = app.findFirstRecordByFilter(collectionName, `${field} = {:value}`, { value })
		} catch {
			record = new Record(app.findCollectionByNameOrId(collectionName))
		}
		for (const key of Object.keys(data)) record.set(key, data[key])
		app.save(record)
		return record
	}

	for (const page of pages) upsert('pages', 'path', page.path, page)
	for (const global of globals) upsert('globals', 'key', global.key, global)
	const form = upsert('forms', 'name', formData.name, formData)
	upsert('form_recipients', 'form', form.id, { form: form.id, addresses: 'info@lumotive.com' })
